ig_mode_t new_mode;
unint32 new_count;
double nis_val = 0.0, wnorm_val = 0.0;
int evaluated = 0;
int invalid = 0;

/* 校验 enable 严格二进制 */
if ((ig_input.enable != 0) && (ig_input.enable != 1))
    invalid = 1;

/* 校验 residual / variance 指针与有限性 */
if (!invalid) {
    if ((ig_input.residual == NULL) || (ig_input.variance == NULL))
        invalid = 1;
}
if (!invalid) {
    if ((!isfinite(ig_input.residual->x)) || (!isfinite(ig_input.residual->y)) ||
        (!isfinite(ig_input.residual->z)) ||
        (!isfinite(ig_input.variance->x)) || (!isfinite(ig_input.variance->y)) ||
        (!isfinite(ig_input.variance->z)))
        invalid = 1;
}

/* 校验每轴方差严格正 */
if (!invalid) {
    if ((ig_input.variance->x <= 0.0) || (ig_input.variance->y <= 0.0) ||
        (ig_input.variance->z <= 0.0))
        invalid = 1;
}

/* 校验阈值与最大连续拒绝次数 */
if (!invalid) {
    double at = ig_config.accept_threshold;
    double rt = ig_config.reject_threshold;
    unint32 mc = ig_config.max_consecutive_reject;
    if ((!isfinite(at)) || (!isfinite(rt)))
        invalid = 1;
    else if (!((at >= 0.0) && (at < rt)))
        invalid = 1;
    if ((mc < 1U) || (mc > 20U))
        invalid = 1;
}

/* 非法输入：锁存 FAULT，use_measurement=0，发布 INFINITY */
if (invalid) {
    ig_state.mode = IG_FAULT;
    ig_output.mode = IG_FAULT;
    ig_output.consecutive_reject = ig_state.consecutive_reject;
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
    ig_output.use_measurement = 0;
    return;
}

/* disable：重置 ACCEPT，发布 ACCEPT/0/0/0/use=1 */
if (ig_input.enable == 0) {
    ig_state.mode = IG_ACCEPT;
    ig_state.consecutive_reject = 0U;
    ig_output.mode = IG_ACCEPT;
    ig_output.consecutive_reject = 0U;
    ig_output.nis = 0.0;
    ig_output.whitened_norm = 0.0;
    ig_output.use_measurement = 1;
    return;
}

/* 计算 whitened 向量、NIS 与 whitened_norm（独立诊断） */
{
    adcs_vec3_t wh;
    wh.x = ig_input.residual->x / sqrt(ig_input.variance->x);
    wh.y = ig_input.residual->y / sqrt(ig_input.variance->y);
    wh.z = ig_input.residual->z / sqrt(ig_input.variance->z);
    nis_val = adcs_vec3_dot(&wh, &wh);
    wnorm_val = adcs_vec3_norm(&wh);
    evaluated = 1;
}

/* 依据决策表分类（保留 prior ACCEPT/REJECT 只在中间区间） */
new_mode = ig_state.mode;
new_count = ig_state.consecutive_reject;

if (nis_val <= ig_config.accept_threshold) {
    new_mode = IG_ACCEPT;
    new_count = 0U;
} else if (nis_val >= ig_config.reject_threshold) {
    new_mode = IG_REJECT;
    new_count += 1U;
    if (new_count >= ig_config.max_consecutive_reject)
        new_mode = IG_FAULT;
} else {
    if (ig_state.mode == IG_REJECT) {
        new_mode = IG_REJECT;
        new_count += 1U;
        if (new_count >= ig_config.max_consecutive_reject)
            new_mode = IG_FAULT;
    } else {
        new_mode = IG_ACCEPT;
    }
}

ig_state.mode = new_mode;
ig_state.consecutive_reject = new_count;

ig_output.mode = new_mode;
ig_output.consecutive_reject = new_count;

/* FAULT 且本周期未评估测量：发布 INFINITY */
if ((new_mode == IG_FAULT) && (!evaluated)) {
    ig_output.nis = INFINITY;
    ig_output.whitened_norm = INFINITY;
} else {
    ig_output.nis = nis_val;
    ig_output.whitened_norm = wnorm_val;
}

/* use_measurement 恰在 mode 为 ACCEPT 时为 1 */
ig_output.use_measurement = (new_mode == IG_ACCEPT) ? 1 : 0;

