{
    adcs_vec3_t whitened;
    double nis;

    whitened.x = ig_input.residual->x / sqrt(ig_input.variance->x);
    whitened.y = ig_input.residual->y / sqrt(ig_input.variance->y);
    whitened.z = ig_input.residual->z / sqrt(ig_input.variance->z);

    nis = adcs_vec3_dot(&whitened, &whitened);
    ig_output.whitened_norm = adcs_vec3_norm(&whitened);
    ig_output.nis = nis;

    if (nis <= ig_config.accept_threshold) {
        ig_state.mode = IG_ACCEPT;
        ig_state.consecutive_reject = 0U;
    } else if (nis >= ig_config.reject_threshold) {
        ig_state.mode = IG_REJECT;
        ig_state.consecutive_reject += 1U;
    } else {
        if (ig_state.mode == IG_REJECT) {
            ig_state.consecutive_reject += 1U;
        } else {
            ig_state.mode = IG_ACCEPT;
            ig_state.consecutive_reject = 0U;
        }
    }

    if (ig_state.mode == IG_REJECT &&
        ig_state.consecutive_reject >= ig_config.max_consecutive_reject) {
        ig_state.mode = IG_FAULT;
    }

    ig_output.mode = ig_state.mode;
    ig_output.consecutive_reject = ig_state.consecutive_reject;
    ig_output.use_measurement = (ig_output.mode == IG_ACCEPT) ? 1 : 0;
}

